import{_ as i,c as a,o as t,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Stopping Waste, Fraud, and Abuse by Eliminating Information Silos","description":"","frontmatter":{"title":"Stopping Waste, Fraud, and Abuse by Eliminating Information Silos","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/stopping-waste-fraud-and-abuse-by-eliminating-information-silos/","publishDate":"2025-03-20T20:47:00-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-21-stopping-waste-fraud-and-abuse-by-eliminating-information-silos.md","filePath":"executive-orders/2025-03-21-stopping-waste-fraud-and-abuse-by-eliminating-information-silos.md"}'),s={name:"executive-orders/2025-03-21-stopping-waste-fraud-and-abuse-by-eliminating-information-silos.md"};function o(r,e,l,d,c,u){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="stopping-waste-fraud-and-abuse-by-eliminating-information-silos" tabindex="-1">Stopping Waste, Fraud, and Abuse by Eliminating Information Silos <a class="header-anchor" href="#stopping-waste-fraud-and-abuse-by-eliminating-information-silos" aria-label="Permalink to &quot;Stopping Waste, Fraud, and Abuse by Eliminating Information Silos&quot;">​</a></h1><p>Published: Friday, March 21, 2025</p><ul><li><p><strong>Objective</strong>: Facilitate Federal employees&#39; access to Government data and promote inter-agency data sharing to reduce inefficiency, duplication, and enhance fraud detection.</p></li><li><p><strong>Definitions</strong>:</p><ul><li><strong>Agency</strong>: Defined as per section 3502 of title 44, U.S. Code, excluding the Executive Office of the President.</li><li><strong>Agency Head</strong>: The highest-ranking official of an agency (e.g., Secretary, Administrator, Director).</li></ul></li><li><p><strong>Directives for Agency Heads</strong>:</p><ul><li>Ensure Federal officials have full and prompt access to unclassified records, data, and systems necessary for identifying and eliminating waste, fraud, and abuse.</li><li>Authorize and facilitate intra- and inter-agency sharing of unclassified agency records.</li><li>Rescind or modify agency guidance that hinders data sharing within 30 days.</li><li>Review regulations governing unclassified data access and report findings to the Office of Management and Budget (OMB) within 30 days.</li><li>Ensure the Federal Government has comprehensive access to data from State programs receiving Federal funding.</li><li>Secretary of Labor and designees to have access to unemployment data and related payment records immediately.</li></ul></li><li><p><strong>Regulatory Modifications</strong>: Changes made under this order are exempt from Executive Order 14192.</p></li><li><p><strong>Review of Classified Information Policies</strong>:</p><ul><li>Conduct a review to assess if current policies unjustifiably classify materials.</li><li>Submit a report to OMB within 45 days with recommendations for improvement.</li></ul></li><li><p><strong>Limitations</strong>:</p><ul><li>The order does not affect the authority of executive departments or the functions of the OMB related to budgetary, administrative, or legislative proposals.</li><li>Implementation is subject to applicable law and available appropriations.</li><li>Does not create enforceable rights or benefits against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/stopping-waste-fraud-and-abuse-by-eliminating-information-silos/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/stopping-waste-fraud-and-abuse-by-eliminating-information-silos/</a></p>',4)]))}const f=i(s,[["render",o]]);export{g as __pageData,f as default};
